def parse_duration(s: str) -> int:
    """Convert a human duration string to whole seconds."""
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    # Try ISO-8601: P[nD]T[nH][nM][nS]
    if s.upper().startswith('P'):
        return _parse_iso8601(s)

    # Try colon form: mm:ss or hh:mm:ss
    if ':' in s:
        return _parse_colon(s)

    # Try bare number (integer or decimal)
    if re.fullmatch(r'\d+(?:\.\d+)?', s):
        return int(float(s))

    # Try unit-based form: e.g., "1h30m", "1.5h", "1d 2h 3m"
    return _parse_units(s)


def _parse_iso8601(s: str) -> int:
    """Parse ISO-8601 duration: P[nD]T[nH][nM][nS]"""
    upper = s.upper()

    if 'T' in upper:
        # With T: P[nD]T[nH][nM][nS] where at least one time component is present
        pattern = r'^P(?:(\d+)D)?T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$'
        m = re.fullmatch(pattern, upper)
        if not m:
            raise ValueError(f"Invalid ISO-8601 duration: {s!r}")
        days = int(m.group(1)) if m.group(1) else 0
        hours = int(m.group(2)) if m.group(2) else 0
        minutes = int(m.group(3)) if m.group(3) else 0
        seconds = int(m.group(4)) if m.group(4) else 0
        # Must have at least one time component (group 2, 3, or 4 matched)
        if not (m.group(2) or m.group(3) or m.group(4)):
            raise ValueError(f"Invalid ISO-8601 duration (T with no time components): {s!r}")
    else:
        # Without T: P[nD]
        pattern = r'^P(\d+)D$'
        m = re.fullmatch(pattern, upper)
        if not m:
            raise ValueError(f"Invalid ISO-8601 duration: {s!r}")
        days = int(m.group(1))
        hours = minutes = seconds = 0

    return days * 86400 + hours * 3600 + minutes * 60 + seconds


def _parse_colon(s: str) -> int:
    """Parse colon form: mm:ss or hh:mm:ss"""
    parts = s.split(':')
    if len(parts) == 2:
        # mm:ss
        if not (parts[0].isdigit() and parts[1].isdigit()):
            raise ValueError(f"Invalid colon format: {s!r}")
        minutes = int(parts[0])
        seconds = int(parts[1])
        if seconds >= 60:
            raise ValueError(f"Invalid colon format (seconds >= 60): {s!r}")
        return minutes * 60 + seconds
    elif len(parts) == 3:
        # hh:mm:ss
        if not (parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit()):
            raise ValueError(f"Invalid colon format: {s!r}")
        hours = int(parts[0])
        minutes = int(parts[1])
        seconds = int(parts[2])
        if minutes >= 60 or seconds >= 60:
            raise ValueError(f"Invalid colon format (min/sec >= 60): {s!r}")
        return hours * 3600 + minutes * 60 + seconds
    else:
        raise ValueError(f"Invalid colon format: {s!r}")


def _parse_units(s: str) -> int:
    """Parse unit-based form: e.g., '1h30m', '1.5h', '1d 2h 3m'"""
    # Remove all spaces for normalized parsing
    normalized = re.sub(r'\s+', '', s)

    # Pattern: (number)(unit), where number can be integer or decimal
    # Units: w, d, h, m, s (case insensitive)
    pattern = r'(\d+(?:\.\d+)?)([wdhms])'
    matches = list(re.finditer(pattern, normalized, re.IGNORECASE))

    if not matches:
        raise ValueError(f"Invalid duration: {s!r}")

    # Check that the entire string is consumed by the matches
    consumed = set()
    for m in matches:
        for i in range(m.start(), m.end()):
            consumed.add(i)
    if len(consumed) != len(normalized):
        raise ValueError(f"Invalid duration (unparsed characters): {s!r}")

    # Check units are in descending order (w > d > h > m > s)
    unit_order = {'w': 0, 'd': 1, 'h': 2, 'm': 3, 's': 4}
    prev_order = -1
    for m in matches:
        unit = m.group(2).lower()
        order = unit_order[unit]
        if order <= prev_order:
            raise ValueError(f"Invalid duration (units not in descending order): {s!r}")
        prev_order = order

    total = 0.0
    for m in matches:
        value = float(m.group(1))
        unit = m.group(2).lower()
        if unit == 'w':
            total += value * 604800
        elif unit == 'd':
            total += value * 86400
        elif unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value

    return int(total)

